// EverGrandeCity_ChampionsRoom (zone 34): generated by converter/gen_interiors.py from Sapphire's simple people and signs.
// Messages: src/text/script/0041_room_EverGrandeCity_ChampionsRoom.txt
#include "asm/field_script.inc"
#include "hoenn.h"  // ch11
#include "hoenn_trainers.h"  // ch11 (before hoenn_story.inc: its macros name trainers)
#include "hoenn_story.inc"  // ch11

    ScriptEntry Script_None
    ScriptEntry CH_Init             // 2: zone init (ChampionsRoom_OnTransition: the rival's sprite; the exit door's warp)  // story:
    ScriptEntry CH_EnterRoom        // 3: OnFrame VAR_TEMP_1 0: ..._EventScript_EnterRoom (Steven, the rival, Birch, the Hall of Fame)  // story:
    ScriptEntriesEnd

Script_None:
    VMHalt
    .balign 4, 0

// ---- story (chapter Ch11, ch11 agent 2026-10-07; Sapphire data/maps/EverGrandeCity_ChampionsRoom/scripts.inc,
// EverGrandeCity_HallOfFame/scripts.inc and data/scripts/hall_of_fame.inc; generators must keep everything from this line on;
// entries above marked "// story:")
// Scripts 2-3, text lines 1-36 (line 0 is the generator's). Room tiles = Sapphire tiles + (1,-1). People (data/story/ch11.json,
// uid = Sapphire local id): Steven 1 (6,5), the rival 2 (6,12, hidden by FLAG_HIDE_RIVAL_CHAMPIONS_ROOM), Prof. Birch 3 (6,12,
// FLAG_HIDE_BIRCH_CHAMPIONS_ROOM); none has a script of its own (Sapphire: 0x0).
// EMERALD (emerald_ch11_gameclear, 2026-10-12; pokeemerald EverGrandeCity_ChampionsRoom): the Champion is WALLACE, not Steven. The
// scene is the same (his entrance speech, the battle, the rival's advice, Birch, "come with me", the walk to the Hall of Fame);
// the object is Wallace's picture (data/story/ch11.json "model_emerald" 288), the words are Emerald's (src/text/script/emerald/
// 0041_room_EverGrandeCity_ChampionsRoom.txt, same rows) and the battle is TRAINER_WALLACE_EMERALD. The names CH_STEVEN /
// T_StevenComeWithMe stay (they are only labels). Steven is a post-game boss in his Meteor Falls cave in Emerald (a map of its own).
// Black 2 differences:
// - The Hall of Fame (halloffame agent, 2026-10-07): Steven and the player walk out through the door as Sapphire does and
//   warp into the Hall of Fame room (zone 57, 0114_room_EverGrandeCity_HallOfFame.s): the walk to the machine, the record,
//   the game-clear flags (EverGrandeCity_HallOfFame_EventScript_SetGameClearFlags, ribbons: moved there) and Black 2's
//   CallGameClear (record screen, save, Hoenn credits, THE END; Continue starts in the player's room).
// - Sapphire's door warp (6,2) -> Hall of Fame stays off the map (the room is left by the scene).
// - Prof. Birch's Pokédex rating (ProfBirch_EventScript_RatePokedex): Hoenn counts of the 202 Hoenn species (Black 2's own
//   Pokédex flags), the rating line for the caught count; the National Dex part is Sapphire's "not enabled" skip. Counts of 200
//   and 201 are rated "complete" (Sapphire looks at Jirachi and Deoxys).
#ifdef HOENN_EMERALD
#include "hoenn_version.inc"                      // TRAINER_WALLACE_EMERALD (kept here: a generator rerun keeps the story part only)
#endif
#define T_IntroSpeech 1
#define T_PostBattleSpeech 2
#define T_MayAdvice 3
#define T_MayItsAlreadyOver 4
#define T_BrendanAdvice 5
#define T_BrendanYouveWon 6
#define T_BirchArriveRatePokedex 7
#define T_BirchCongratulations 8
#define T_StevenComeWithMe 9
#define T_StevenWaitOutside 10
#define T_MayCongratulations 11
#define T_BrendanCongratulations 12
#define T_HereWeHonor 13                            /* lines 13-14: unused here since the Hall of Fame room says them (0066) */
#define T_LetsRecord 14
#define T_SoYouveSeen 15
#define T_Rating10 16
#define T_DexCompleted 36
#define T_BirchArriveRatePokedexBrendan 37          /* the same line with Brendan (the rival of a girl): {RIVAL} is never stored in this port */
#define CH_STEVEN 1
#define CH_RIVAL 2
#define CH_BIRCH 3
#define CH_EXIT_WARP 1
#define CH_PARTY_SLOT 0x8065
#define CH_TMP 0x8066
#define CH_RIBBON_GET 0x8067
#define C11_DEXKIND 0x8062                       /* scenes/ch11_dexcount.inc: kind in, count out */
#define C11_DEXCOUNT 0x8063
#define C11_DEXTMP 0x8064

CH_Init:                                         // EverGrandeCity_ChampionsRoom_OnTransition
#ifdef HOENN_TEST_CH11
    VMCall Test_Ch11Start                        // test builds only (scenes/ch11_test.inc)
#endif
    h_setup_rival_gfx                            // Common_EventScript_SetupRivalGfxId
    ObjInitWarpGPos CH_EXIT_WARP, 0, 0, 0        // the door to the Hall of Fame: the scene walks through it
    VMHalt

CH_EnterRoom:                                    // EverGrandeCity_ChampionsRoom_EventScript_EnterRoom
    ActorsPauseAll
    h_applymovement 255, Common_Movement_WalkUp4
    h_waitmovement
    VMSleep 20                                   // delay 40
    h_applymovement 255, Mv_CH_PlayerApproachSteven
    h_waitmovement
    h_setvar 0x4001, 1                           // VAR_TEMP_1 1 (once a visit)
    // goto EverGrandeCity_ChampionsRoom_EventScript_Steven
    BGMPlay MUS_ENCOUNTER_CHAMPION               // playbgm MUS_ENCOUNTER_CHAMPION
    h_buffer_player
    h_msgbox_actor T_IntroSpeech, CH_STEVEN      // Steven: Welcome, <player>. I was looking forward to seeing you here one day. ...
    h_closemessage
    h_setflag FLAG_E4_BATTLE_PENDING             // (cleared when won; still set after a whiteout: the League lobby resets the Elite Four)
#ifndef HOENN_TEST_CH11S                         /* test builds only (HOENN_TEST_CH11S=1): skip the battle (the tests have one Lv 100 Pokémon) */
#ifdef HOENN_EMERALD
    h_trainerbattle TRAINER_WALLACE_EMERALD      // Emerald: the Champion is Wallace (same Black 2 trainer id as Sapphire's Steven; party, class and picture from emerald_data)
#else
    h_trainerbattle TRAINER_STEVEN               // (in battle: "I, the Champion, fall in defeat... Kudos to you, <player>! ...")
#endif
#endif
    h_clearflag FLAG_E4_BATTLE_PENDING
    // EverGrandeCity_ChampionsRoom_EventScript_Defeated
    SEPlay SEQ_SE_KAIDAN                         // SE_DOOR: the door opens (the room's door model stays as built)
    h_buffer_player
    h_msgbox_actor T_PostBattleSpeech, CH_STEVEN // Steven: Congratulations! ... You are rightfully the Hoenn region's new...
    h_closemessage
    SEPlay SEQ_SE_KAIDAN                         // SE_DOOR
    h_goto_if_girl L_CH_BrendanMusic
    BGMPlay MUS_ENCOUNTER_MAY                    // call_if_eq PlayMayMusic (the rival of a boy is May)
    VMJump L_CH_RivalArrives
L_CH_BrendanMusic:
    BGMPlay MUS_ENCOUNTER_BRENDAN
L_CH_RivalArrives:
    h_addobject CH_RIVAL, FLAG_HIDE_RIVAL_CHAMPIONS_ROOM        // addobject 2
    h_applymovement CH_RIVAL, Mv_CH_RivalApproachPlayer          // ..._EventScript_RivalApproachPlayer
    h_waitmovement
    h_applymovement 255, Common_Movement_WalkInPlaceFastestLeft
    h_waitmovement
    h_buffer_player
    h_msgbox_gendered T_MayAdvice, T_BrendanAdvice, CH_RIVAL     // May / Brendan: <player>! Here's some advice before you challenge the Champion...
    h_closemessage                               // (an open window before a movement list crashes Black 2)
    VMSleep 20                                   // delay 40
    h_applymovement CH_RIVAL, Common_Movement_ExclamationMark    // playse SE_PIN + "!"
    h_waitmovement
    h_applymovement CH_RIVAL, Common_Movement_Delay48
    h_waitmovement
    h_applymovement CH_RIVAL, Mv_CH_RivalLookBackAndForth
    h_waitmovement
    h_msgbox_gendered T_MayItsAlreadyOver, T_BrendanYouveWon, CH_RIVAL   // Huh? What, what, what? <player>... Could it be that... It's already over?
    // ..._EventScript_BirchArrivesExitForHoF
    h_closemessage
    h_addobject CH_BIRCH, FLAG_HIDE_BIRCH_CHAMPIONS_ROOM
    h_applymovement CH_BIRCH, Mv_CH_BirchArrives
    h_waitmovement
    h_applymovement 255, Common_Movement_WalkInPlaceFastestRight
    h_waitmovement
    h_buffer_player
    h_msgbox_gendered T_BirchArriveRatePokedex, T_BirchArriveRatePokedexBrendan, CH_BIRCH   // Prof. Birch: See? What did I tell you, May / Brendan? ... Here, let me see.
    VMCall CH_RatePokedex                        // call ProfBirch_EventScript_RatePokedex
    h_msgbox_actor T_BirchCongratulations, CH_BIRCH     // Prof. Birch: Anyways, congratulations! Now, go proudly into the final room!
    h_closemessage
    h_applymovement CH_STEVEN, Common_Movement_WalkInPlaceFastestUp
    h_waitmovement
    VMSleep 10                                   // delay 20
    h_applymovement CH_STEVEN, Common_Movement_WalkInPlaceFastestDown
    h_waitmovement
    h_buffer_player
    h_msgbox_actor T_StevenComeWithMe, CH_STEVEN        // Steven: <player>... No, the new Champion! Come with me.
    h_closemessage
    VMSleep 15                                   // delay 30
    h_applymovement CH_STEVEN, Mv_CH_StevenExitStart
    h_applymovement 255, Mv_CH_PlayerExitStart
    h_applymovement CH_BIRCH, Common_Movement_WalkInPlaceFastestUp
    h_applymovement CH_RIVAL, Mv_CH_RivalFollows
    h_waitmovement
    VMSleep 10                                   // delay 20
    h_applymovement 255, Common_Movement_WalkInPlaceFastestDown
    h_waitmovement
    h_msgbox_actor T_StevenWaitOutside, CH_STEVEN       // Steven: I'm sorry, but... From here on, only those Trainers who have become Champions may enter. ...
    h_msgbox_gendered T_MayCongratulations, T_BrendanCongratulations, CH_RIVAL   // May: Groan... I'm just joking! ... Honestly, congratulations!
    h_closemessage
    h_applymovement CH_STEVEN, Mv_CH_StevenExit
    h_applymovement 255, Mv_CH_PlayerExit
    h_waitmovement
    h_setflag FLAG_HIDE_PETALBURG_GYM_GUIDE
    h_setflag FLAG_HIDE_RIVAL_CHAMPIONS_ROOM     // (the rival and Birch are gone again on the next visit: addobject cleared their flags)
    h_setflag FLAG_HIDE_BIRCH_CHAMPIONS_ROOM
    // warp MAP_EVER_GRANDE_CITY_HALL_OF_FAME, 255, 7, 16: the Hall of Fame room (zone 57, the halloffame agent's
    // 0114_room_EverGrandeCity_HallOfFame.s): its script 2 walks Steven and the player to the machine, records the team,
    // sets the game-clear flags and runs Black 2's record screen, save and credits (CallGameClear)
    h_warp_scene 57, 8, 16, 0, 2
    h_release

CH_RatePokedex:                                  // ProfBirch_EventScript_RatePokedex (Hoenn counts; the National Dex is not enabled)
    WorkSetConst C11_DEXKIND, 0
    VMCall Sub_C11_CountDex
    WorkSet 0x8060, C11_DEXCOUNT                 // seen
    WorkSetConst C11_DEXKIND, 1
    VMCall Sub_C11_CountDex
    WorkSet 0x8061, C11_DEXCOUNT                 // caught
    WordSetNumber 1, 0x8060, 3                   // buffernumberstring 0 (STR_VAR_1)
    WordSetNumber 2, 0x8061, 3                   // buffernumberstring 1 (STR_VAR_2)
    h_msgbox_actor T_SoYouveSeen, CH_BIRCH       // Hmhm... So, you've seen N Pokémon, and you've caught N Pokémon...
    WorkSet CH_TMP, 0x8061                       // ProfBirch_EventScript_ShowRatingMessage: the line for the caught count
    h_goto_if_ge CH_TMP, 200, L_CH_RateComplete
    WorkDiv CH_TMP, 10
    WorkAdd CH_TMP, T_Rating10
    ActorMsg MSGFILE_SCRIPT, CH_TMP, CH_BIRCH, 0, 0   // (the rating line, a work holds its number)
    LastKeyWait
    VMReturn
L_CH_RateComplete:
    ActorMsg MSGFILE_SCRIPT, T_DexCompleted, CH_BIRCH, 0, 0   // Congratulations! Your Pokédex is complete!
    LastKeyWait
    VMReturn

    .balign 4, 0
Mv_CH_PlayerApproachSteven:                      // EverGrandeCity_ChampionsRoom_Movement_PlayerApproachSteven
    walk_up 2
    step_end
Mv_CH_PlayerExitStart:
    walk_up 2
    step_end
Mv_CH_PlayerExit:
    walk_up
    delay_16
    walk_up
    delay_8
    set_invisible
    step_end
Mv_CH_RivalApproachPlayer:
    walk_up 5
    walk_left
    walk_up
    walk_in_place_fastest_right
    step_end
Mv_CH_RivalLookBackAndForth:
    walk_in_place_fastest_up
    delay_16
    walk_in_place_fastest_right
    delay_16
    walk_in_place_fastest_up
    delay_8
    walk_in_place_fastest_right
    delay_16
    step_end
Mv_CH_RivalFollows:
    walk_right
    walk_up
    step_end
Mv_CH_StevenExitStart:
    walk_up 2
    walk_in_place_fastest_down
    step_end
Mv_CH_StevenExit:
    walk_up
    delay_8
    set_invisible
    step_end
Mv_CH_BirchArrives:
    walk_up 5
    walk_right
    walk_up
    walk_in_place_fastest_left
    step_end

#include "common/movement.inc"
#include "scenes/ch11_dexcount.inc"
#include "scenes/ch11_test.inc"
